package com.gaurav.datasave;
import android.app.*;import android.os.*;import android.content.*;import android.database.Cursor;import android.graphics.*;import android.graphics.drawable.*;import android.net.*;import android.provider.ContactsContract;import android.view.*;import android.widget.*;import org.json.*;
public class MainActivity extends Activity{
 LinearLayout root,list; SharedPreferences sp; EditText phone; int N=Color.rgb(0,255,90),D=Color.rgb(0,20,15); static final int PICK=71;
 int dp(float x){return(int)(x*getResources().getDisplayMetrics().density+.5f);} GradientDrawable box(int c,float r,int sw){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));if(sw>0)g.setStroke(dp(sw),N);return g;}
 TextView t(String s,float z){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(Color.WHITE);v.setPadding(dp(10),dp(7),dp(10),dp(7));v.setGravity(Gravity.CENTER_VERTICAL);return v;}
 EditText f(String h){EditText e=new EditText(this);e.setHint(h);e.setHintTextColor(Color.rgb(180,200,193));e.setTextColor(Color.WHITE);e.setTextSize(14);e.setSingleLine();e.setPadding(dp(12),0,dp(12),0);e.setBackground(box(Color.argb(225,2,39,31),12,1));return e;}
 Button b(String s){Button x=new Button(this);x.setText(s);x.setAllCaps(false);x.setTextColor(Color.WHITE);x.setTextSize(12);x.setBackground(box(Color.rgb(0,83,54),14,1));return x;}
 public void onCreate(Bundle x){super.onCreate(x);sp=getSharedPreferences("shops",0);draw();}
 void draw(){ScrollView sc=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(12),dp(12),dp(12),dp(22));GradientDrawable gd=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{Color.rgb(0,10,8),Color.rgb(0,54,34),Color.rgb(0,13,10)});root.setBackground(gd);
 LinearLayout h=new LinearLayout(this);TextView menu=t("☰",28);h.addView(menu,new LinearLayout.LayoutParams(dp(55),dp(70)));TextView logo=t("GAURAV\nDATA SAVE",29);logo.setGravity(17);logo.setTypeface(Typeface.DEFAULT_BOLD);logo.setTextColor(N);h.addView(logo,new LinearLayout.LayoutParams(0,dp(88),1));TextView sec=t("🛡\nSecure",11);sec.setGravity(17);sec.setTextColor(N);h.addView(sec,new LinearLayout.LayoutParams(dp(72),dp(70)));root.addView(h);TextView tag=t("SAVE TODAY  •  GROW TOMORROW",12);tag.setGravity(17);root.addView(tag);
 stats();EditText search=f("⌕  Search shop, phone, area, category...");add(search,-1,dp(52),0,dp(8));TextView at=t("⊕  Add Shop / Party",20);at.setTextColor(N);at.setTypeface(Typeface.DEFAULT_BOLD);root.addView(at);
 EditText name=f("🏪  Shop / Party Name");phone=f("☎  Phone Number");Button contacts=b("👤");contacts.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_PICK,ContactsContract.CommonDataKinds.Phone.CONTENT_URI);startActivityForResult(i,PICK);});LinearLayout pr=new LinearLayout(this);pr.addView(phone,new LinearLayout.LayoutParams(0,dp(52),1));LinearLayout.LayoutParams cb=new LinearLayout.LayoutParams(dp(58),dp(52));cb.setMargins(dp(5),0,0,0);pr.addView(contacts,cb);
 EditText maps=f("🔗  Google Maps Location / Link"),area=f("⌖  Area (e.g. Paharganj, Delhi)"),cat=f("▦  Category"),note=f("✎  Note (optional)");pair(name,pr);pair(maps,area);pair(cat,note);
 Button save=b("▣   SAVE LOCATION");save.setTextSize(17);save.setTypeface(Typeface.DEFAULT_BOLD);add(save,-1,dp(58),dp(5),dp(10));LinearLayout sh=new LinearLayout(this);TextView st=t("SAVED SHOPS",18);st.setTextColor(N);st.setTypeface(Typeface.DEFAULT_BOLD);sh.addView(st,new LinearLayout.LayoutParams(0,dp(48),1));Button sort=b("Sort: Newest⌄");sh.addView(sort,new LinearLayout.LayoutParams(dp(125),dp(44)));root.addView(sh);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);root.addView(list);
 save.setOnClickListener(v->{if(name.getText().toString().trim().isEmpty()){Toast.makeText(this,"Shop name required",0).show();return;}try{JSONArray a=new JSONArray(sp.getString("data","[]"));JSONObject o=new JSONObject();o.put("n",name.getText());o.put("p",phone.getText());o.put("m",maps.getText());o.put("a",area.getText());o.put("c",cat.getText());o.put("no",note.getText());o.put("fav",false);o.put("visited",false);o.put("time",System.currentTimeMillis());a.put(o);sp.edit().putString("data",a.toString()).apply();draw();}catch(Exception e){}});
 search.setOnEditorActionListener((v,id,e)->{render(search.getText().toString());return false;});render("");nav();sc.addView(root);setContentView(sc);}
 void pair(View a,View b){LinearLayout r=new LinearLayout(this);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(52),1);p.setMargins(dp(2),dp(4),dp(2),dp(4));r.addView(a,p);r.addView(b,p);root.addView(r);}void add(View v,int w,int h,int mt,int mb){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(w,h);p.setMargins(0,dp(mt),0,dp(mb));root.addView(v,p);}
 void stats(){int total=0,fav=0,vis=0,today=0;try{JSONArray a=new JSONArray(sp.getString("data","[]"));total=a.length();long d=86400000L;for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);if(o.optBoolean("fav"))fav++;if(o.optBoolean("visited"))vis++;if(System.currentTimeMillis()-o.optLong("time",0)<d)today++;}}catch(Exception e){}String[] s={"🏪\nTotal Shops\n"+total,"👥\nVisited\n"+vis,"★\nFavourites\n"+fav,"▣\nToday\n"+today};int[] c={Color.rgb(0,105,55),Color.rgb(0,100,180),Color.rgb(190,130,0),Color.rgb(110,35,160)};LinearLayout r=new LinearLayout(this);for(int i=0;i<4;i++){final int mode=i;TextView x=t(s[i],11);x.setGravity(17);x.setTypeface(Typeface.DEFAULT_BOLD);x.setBackground(box(c[i],14,1));x.setOnClickListener(v->renderMode(mode));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(78),1);p.setMargins(dp(2),dp(8),dp(2),dp(8));r.addView(x,p);}root.addView(r);}
 void renderMode(int mode){render(mode==2?"#FAV#":mode==1?"#VIS#":mode==3?"#TODAY#":"");}
 void render(String q){list.removeAllViews();try{JSONArray a=new JSONArray(sp.getString("data","[]"));for(int i=a.length()-1;i>=0;i--){JSONObject o=a.getJSONObject(i);if(q.equals("#FAV#")&&!o.optBoolean("fav"))continue;if(q.equals("#VIS#")&&!o.optBoolean("visited"))continue;if(q.equals("#TODAY#")&&System.currentTimeMillis()-o.optLong("time",0)>=86400000L)continue;if(!q.isEmpty()&&!q.startsWith("#")&&!o.toString().toLowerCase().contains(q.toLowerCase()))continue;final int ix=i;LinearLayout c=new LinearLayout(this);c.setGravity(16);c.setPadding(dp(9),dp(6),dp(7),dp(6));c.setBackground(box(Color.argb(238,2,40,32),13,1));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,dp(82));cp.setMargins(0,dp(3),0,dp(3));c.setLayoutParams(cp);TextView info=t(o.optString("n")+(o.optBoolean("fav")?"  ★":"")+"\n☎ "+o.optString("p")+"\n⌖ "+o.optString("a"),13);info.setTypeface(Typeface.DEFAULT_BOLD);info.setOnClickListener(v->toggle(ix,"visited"));c.addView(info,new LinearLayout.LayoutParams(0,-1,1));String ph=o.optString("p"),mp=o.optString("m");Button fav=b(o.optBoolean("fav")?"★":"☆");fav.setOnClickListener(v->toggle(ix,"fav"));c.addView(fav,new LinearLayout.LayoutParams(dp(43),dp(48)));Button call=b("☎");call.setOnClickListener(v->startActivity(new Intent(Intent.ACTION_DIAL,Uri.parse("tel:"+ph))));c.addView(call,new LinearLayout.LayoutParams(dp(43),dp(48)));Button wa=b("W");wa.setOnClickListener(v->{String z=ph.replaceAll("\\D","");if(z.length()==10)z="91"+z;startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://wa.me/"+z)));});c.addView(wa,new LinearLayout.LayoutParams(dp(43),dp(48)));Button map=b("⌖");map.setOnClickListener(v->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(mp)));}catch(Exception e){}});c.addView(map,new LinearLayout.LayoutParams(dp(43),dp(48)));list.addView(c);}}catch(Exception e){}}
 void toggle(int i,String k){try{JSONArray a=new JSONArray(sp.getString("data","[]"));JSONObject o=a.getJSONObject(i);o.put(k,!o.optBoolean(k));sp.edit().putString("data",a.toString()).apply();draw();}catch(Exception e){}}
 void nav(){LinearLayout n=new LinearLayout(this);String[] s={"⌂\nHome","＋\nAdd","⌖\nMap","▥\nReports","⚙\nMore"};for(String q:s){TextView x=t(q,12);x.setGravity(17);x.setTextColor(q.contains("Home")?N:Color.LTGRAY);n.addView(x,new LinearLayout.LayoutParams(0,dp(62),1));}n.setBackground(box(Color.argb(245,1,35,28),15,1));root.addView(n);}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==PICK&&c==RESULT_OK&&d!=null){Cursor cur=getContentResolver().query(d.getData(),new String[]{ContactsContract.CommonDataKinds.Phone.NUMBER},null,null,null);if(cur!=null&&cur.moveToFirst()){phone.setText(cur.getString(0));cur.close();}}}
}